// MetaMask Direct can leave approval promises pending when its app is closed.
// Offer a local reset after returning; never expire an approval in the wallet,
// infer that a transaction was cancelled, or replay a request automatically.
export function metaMaskRequestResetError() {
  const error = new Error('Wallet reset. Reconnect; check MetaMask Activity before retrying an approved transaction.');
  error.code = 'METAMASK_REQUEST_RESET';
  return error;
}

export function guardMetaMaskRequests(raw, {
  approvalMethods,
  onStalled,
  onCleared,
  document: doc = globalThis.document,
  window: win = globalThis.window,
  returnDelayMs = 10_000,
  initialDelayMs = 20_000,
}) {
  const pending = new Set();
  let retired = false;
  let timer = null;

  function clearTimer() {
    if (timer !== null) clearTimeout(timer);
    timer = null;
  }

  function schedule(delay) {
    if (retired || pending.size === 0 || doc?.visibilityState === 'hidden') return;
    clearTimer();
    timer = setTimeout(() => {
      timer = null;
      if (!retired && pending.size && doc?.visibilityState !== 'hidden') onStalled();
    }, delay);
    timer?.unref?.();
  }

  function onVisibility() {
    clearTimer();
    if (doc?.visibilityState !== 'hidden') schedule(returnDelayMs);
  }

  function onFocus() {
    // Some mobile browsers restore focus without a visibility transition.
    if (timer === null) schedule(returnDelayMs);
  }

  async function run(request) {
    if (retired) throw metaMaskRequestResetError();
    let rejectWait;
    const abandoned = new Promise((_, reject) => { rejectWait = reject; });
    const entry = { reject: rejectWait };
    pending.add(entry);
    if (pending.size === 1) {
      doc?.addEventListener?.('visibilitychange', onVisibility);
      win?.addEventListener?.('focus', onFocus);
      schedule(initialDelayMs);
    }
    try {
      // Attach both handlers before invoking the SDK. Late responses remain
      // consumed after reset, but cannot complete or replay the abandoned call.
      return await Promise.race([abandoned, Promise.resolve().then(() => {
        if (retired) throw metaMaskRequestResetError();
        return request();
      })]);
    } finally {
      pending.delete(entry);
      if (pending.size === 0) cleanup();
    }
  }

  function cleanup() {
    clearTimer();
    doc?.removeEventListener?.('visibilitychange', onVisibility);
    win?.removeEventListener?.('focus', onFocus);
    onCleared();
  }

  function retire() {
    if (retired) return;
    retired = true;
    for (const entry of pending) entry.reject(metaMaskRequestResetError());
    pending.clear();
    cleanup();
  }

  const provider = new Proxy(raw, {
    get(target, key) {
      if (key === 'request') return (payload) => {
        if (retired) return Promise.reject(metaMaskRequestResetError());
        if (approvalMethods.has(payload?.method)) return run(() => target.request(payload));
        return target.request(payload);
      };
      const value = Reflect.get(target, key, target);
      return typeof value === 'function' ? value.bind(target) : value;
    },
  });

  return { provider, run, retire };
}
